import{_ as o,o as t,c as a,ag as d}from"./chunks/framework.BKVF-9lJ.js";const u=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md","lastUpdated":1791840224000}'),s={name:"troubleshooting.md"};function r(c,e,i,n,l,h){return t(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p>Start with the built-in diagnostics, run from the project root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # human-readable; exit code 2 when a check fails</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # { ok, summary: { pass, warn, fail }, checks: [{ id, status, message, hint }] }</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # manifest and port validation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mfe-forge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # what the CLI discovered</span></span></code></pre></div><p>Include the <code>doctor --json</code> output when you <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/issues" target="_blank" rel="noreferrer">report a bug</a>.</p><h2 id="doctor-checks" tabindex="-1">Doctor checks <a class="header-anchor" href="#doctor-checks" aria-label="Permalink to &quot;Doctor checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check id</th><th>Failure message</th><th>Fix</th></tr></thead><tbody><tr><td><code>node-version</code></td><td><code>Node vX is too old</code></td><td>Install Node.js 20 or newer.</td></tr><tr><td><code>lockfile</code></td><td><code>No lock file found for &lt;pm&gt;</code></td><td>Run <code>&lt;pm&gt; install</code>. The expected file is <code>bun.lock</code>/<code>bun.lockb</code>, <code>pnpm-lock.yaml</code> or <code>package-lock.json</code> depending on <code>defaults.packageManager</code>. If you switched package managers, update the config with <code>mfe-forge config --set defaults.packageManager --value &lt;pm&gt;</code>.</td></tr><tr><td><code>ports</code></td><td><code>Port conflicts: a and b both use port N</code></td><td>Change <code>port</code> in one <code>vite.config.ts</code> (both <code>server</code> and <code>preview</code>) and the <code>--port</code> in that app&#39;s <code>dev</code> and <code>preview</code> scripts.</td></tr><tr><td><code>hosts</code></td><td><code>Scopes without a host: x</code></td><td><code>mfe-forge generate host x/host</code>. Only reported when the project has at least one app.</td></tr><tr><td><code>workspaces</code></td><td><code>Root package.json missing workspaces configuration</code></td><td>Add <code>&quot;workspaces&quot;: [&quot;apps/*/*&quot;, &quot;packages/*&quot;]</code>. The check only verifies the field exists, not that it matches your apps.</td></tr></tbody></table><h2 id="commands-run-from-the-wrong-directory" tabindex="-1">Commands run from the wrong directory <a class="header-anchor" href="#commands-run-from-the-wrong-directory" aria-label="Permalink to &quot;Commands run from the wrong directory&quot;">​</a></h2><p><strong>Symptom:</strong> <code>No apps found to run</code>, <code>App &quot;x&quot; not found</code>, <code>doctor</code> reports <code>No root package.json found</code>, or <code>config --show</code> prints a <code>name</code> that is your current folder name.</p><p>The CLI uses the <strong>current working directory</strong> as the project root and does not search parent directories for <code>apps/</code>. <code>cd</code> to the folder that contains <code>mfeforge.config.js</code> and <code>apps/</code>.</p><h2 id="configuration-errors" tabindex="-1">Configuration errors <a class="header-anchor" href="#configuration-errors" aria-label="Permalink to &quot;Configuration errors&quot;">​</a></h2><p><strong><code>Invalid MFE Forge configuration:</code> followed by <code>path: message</code> lines, exit code 3.</strong> The config parsed but failed the schema. Common cases: <code>defaults.packageManager</code> not one of <code>bun</code>, <code>pnpm</code>, <code>npm</code>; <code>dev.portRange</code> not a two-number array; an unknown enum value in <code>testing</code>, <code>ci</code> or <code>federation.plugin</code>. Run <code>mfe-forge config --validate</code> to list the issues.</p><p><strong><code>Warning: Failed to load .../mfeforge.config.ts: ... Falling back to default configuration.</code></strong> The <code>.ts</code> loader does not compile TypeScript. It strips imports, comments, simple type annotations and <code>as</code>/<code>satisfies</code>, then evaluates the default export. It fails on:</p><ul><li><code>No default export found in configuration file</code>;</li><li>references to imported values (the imports are removed, so the identifiers are undefined);</li><li>a default export that is not an object: <code>Default export must evaluate to a configuration object</code>;</li><li>TypeScript syntax beyond the simple cases (interfaces, enums, complex generics).</li></ul><p>Keep the default export a self-contained object literal. When this warning appears, every command runs with default settings, including the <code>bun</code> package manager.</p><h2 id="generation-errors" tabindex="-1">Generation errors <a class="header-anchor" href="#generation-errors" aria-label="Permalink to &quot;Generation errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Invalid type &quot;x&quot;. Valid: app, host, package, design-system, library, pkg</code></td><td>Unknown generator</td><td>Use one of the listed types. <code>pkg</code> is an alias of <code>package</code>.</td></tr><tr><td><code>Apps and hosts must be scoped: &quot;x&quot; → try &quot;x-scope/x&quot;</code></td><td>Missing scope</td><td>Use <code>scope/name</code>, for example <code>shop/catalog</code>.</td></tr><tr><td><code>Directory already exists: &lt;path&gt;</code></td><td>Target exists</td><td>Pick another name or remove the directory. <code>init</code> prints <code>Directory &lt;name&gt; already exists</code>.</td></tr><tr><td><code>Host &quot;x/host&quot; not found. Run &quot;mfe-forge generate host x/host&quot; to create it.</code></td><td>Remote generated before its host (warning only)</td><td>Generate the host; it picks up existing remotes of its scope. Or pass <code>--host &lt;scope/host&gt;</code> / <code>--skip-host</code>.</td></tr><tr><td><code>No available ports found in the configured range</code></td><td>Every port in <code>dev.portRange</code> is used or bound</td><td>Widen <code>dev.portRange</code> or pass <code>--port</code>.</td></tr><tr><td><code>Template error: ...</code></td><td>Template rendering failed</td><td>The partial directory is removed. Report it as a bug.</td></tr></tbody></table><p>Names entered at the interactive prompt must match <code>^[a-z][a-z0-9-/]*$</code>. An <code>@org/</code> prefix on the name is stripped.</p><h2 id="host-does-not-pick-up-a-remote" tabindex="-1">Host does not pick up a remote <a class="header-anchor" href="#host-does-not-pick-up-a-remote" aria-label="Permalink to &quot;Host does not pick up a remote&quot;">​</a></h2><p><strong><code>Warning: &quot;remotes: {&quot; section not found in .../vite.config.ts</code></strong> (from <code>generate</code>) or <strong><code>Warning: Could not find &quot;remotes: {&quot; section in ...</code></strong> (from <code>sync</code>). The CLI locates the host&#39;s remotes with a regular expression on the literal text <code>remotes: {</code>. If you moved remotes into a variable, a spread or a helper function, the CLI cannot update them; keep an inline <code>remotes: { ... }</code> object in the federation call.</p><p>Other causes:</p><ul><li>The remote is in another scope. A host only receives remotes from its own <code>apps/&lt;scope&gt;/</code>.</li><li>The remote directory has no <code>vite.config.ts</code>, so discovery ignores it.</li><li>The block contains hand-written entries: <code>sync</code> replaces the entire block, so they are removed. Keep manual remotes outside the CLI-managed block or re-add them after syncing.</li></ul><p><code>mfe-forge sync --dry-run --diff</code> shows which files would change without writing.</p><h2 id="remote-fails-to-load-in-the-host" tabindex="-1">Remote fails to load in the host <a class="header-anchor" href="#remote-fails-to-load-in-the-host" aria-label="Permalink to &quot;Remote fails to load in the host&quot;">​</a></h2><p><strong>The host shows &quot;Something went wrong&quot; for a remote, or the browser console reports a failed request for <code>remoteEntry.js</code>.</strong></p><ol><li>With <code>@originjs/vite-plugin-federation</code>, a remote served by <code>vite</code> (dev mode) does not provide <code>/assets/remoteEntry.js</code>. Build the remote and serve it with <code>vite preview</code> (the generated <code>preview</code> script), as shown in the <a href="./quick-start#_6-install-and-run">Quick start</a>.</li><li>Check the port: the host&#39;s <code>remotes</code> URL must match the remote&#39;s <code>preview.port</code>. Run <code>mfe-forge sync</code> after changing ports.</li><li>In production, the remote URL still points at <code>http://localhost:&lt;port&gt;</code>; see <a href="./publishing#point-hosts-at-deployed-remotes">Publishing</a>.</li><li>After fixing the cause, click <strong>Try again</strong>. <code>LazyRemote</code> and <code>RemoteLoader</code> create a new import on reset. If you use your own <code>React.lazy</code>, a rejected import stays rejected until the page reloads.</li></ol><p><strong>The host page is replaced by the remote&#39;s UI, or React warns about calling <code>createRoot</code> on a container that already has a root.</strong> The app template exposes <code>./App</code> as <code>./src/bootstrap.tsx</code>, which mounts into <code>#root</code> when imported. Expose <code>./src/App.tsx</code> instead; <code>main.tsx</code> still loads <code>bootstrap.tsx</code> for standalone runs.</p><p><strong>Events or global state do not reach other MFEs.</strong> <code>globalEventBus</code> and <code>useGlobalStore</code> are module-level state. Unless <code>@mfe-forge/core</code> and <code>@mfe-forge/store</code> are listed as <code>singleton</code> in <code>shared</code> in the host and every remote, each bundle has its own copy. See <a href="./concepts#shared-dependencies">Concepts</a>.</p><p><strong>&quot;Invalid hook call&quot; or two React copies.</strong> Keep <code>react</code>, <code>react-dom</code>, <code>react-router-dom</code> and <code>zustand</code> as singletons with the same <code>requiredVersion</code> in every app, and install one React version across the workspace. <code>mfe-forge deps --check</code> reports differing versions of <code>federation.shared</code> dependencies among packages under <code>packages/</code>.</p><h2 id="dev-server-problems" tabindex="-1">Dev server problems <a class="header-anchor" href="#dev-server-problems" aria-label="Permalink to &quot;Dev server problems&quot;">​</a></h2><ul><li><strong><code>dev:&lt;scope&gt;:&lt;name&gt;</code> fails with &quot;No packages matched the filter&quot; or a missing workspace.</strong> The root <code>workspaces</code> glob does not include <code>apps/*/*</code>. See <a href="./installation#workspace-layout-fix">Installation</a>. With pnpm, add <code>pnpm-workspace.yaml</code>.</li><li><strong>Only the first app starts.</strong> In multi-app mode <code>dev</code> runs <code>npx --yes concurrently</code>. If that fails (for example offline without <code>concurrently</code> in the cache), it falls back to running scripts one after another, and the first long-running server blocks the rest. Install <code>concurrently</code> as a dev dependency or start apps individually.</li><li><strong><code>--build-watch</code> has no effect.</strong> The flag is accepted but not implemented yet.</li><li><strong><code>--parallel</code> on <code>dev</code></strong> is accepted but not used to limit processes.</li></ul><h2 id="build-and-test-failures" tabindex="-1">Build and test failures <a class="header-anchor" href="#build-and-test-failures" aria-label="Permalink to &quot;Build and test failures&quot;">​</a></h2><ul><li><code>build</code> prints <code>✔ built N, ✖ failed M</code> and exits with code <code>2</code> and <code>Build failed for: ...</code> when any app fails. The stderr of each failed build is printed. Add <code>--bail</code> to stop at the first failure.</li><li><code>build --scope x</code> with no apps fails with <code>No apps found in scope &quot;x&quot;</code>.</li><li><code>build</code> runs each app&#39;s own <code>build</code> script (<code>tsc -b &amp;&amp; vite build</code>), so TypeScript errors fail the build.</li><li><code>--analyze</code> and <code>--parallel</code> are accepted on <code>build</code> but do not change behaviour; builds run sequentially.</li><li><code>test</code> with both <code>--unit</code> and <code>--e2e</code> fails with <code>Use either --unit or --e2e, not both</code>. A failing script yields <code>Tests failed</code> and exit code <code>2</code>.</li><li>The generated <code>test</code> script is plain <code>vitest</code>, which watches when run in an interactive terminal. Use <code>CI=1 mfe-forge test</code> for a single run. Generated hosts do not list <code>vitest</code> as a dependency.</li></ul><h2 id="ports" tabindex="-1">Ports <a class="header-anchor" href="#ports" aria-label="Permalink to &quot;Ports&quot;">​</a></h2><p>Discovery reads only the first literal <code>port: &lt;number&gt;</code> in each <code>vite.config.ts</code>, and allocation also reads <code>--port &lt;number&gt;</code> in <code>dev</code> scripts. Ports from environment variables are invisible to the CLI, so discovery reports <code>3000</code> and new apps may collide. Keep ports literal.</p><h2 id="package-names-with-an-organization" tabindex="-1">Package names with an organization <a class="header-anchor" href="#package-names-with-an-organization" aria-label="Permalink to &quot;Package names with an organization&quot;">​</a></h2><p>Set <code>organization</code> without the <code>@</code> (<code>acme</code>, not <code>@acme</code>). The CLI prepends <code>@</code> when it builds package names, so <code>@acme</code> produces <code>@@acme/shop-catalog</code>.</p><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><p>Check <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/docs/ai/known-issues.md" target="_blank" rel="noreferrer">known issues</a>, then open an issue with the <code>doctor --json</code> output, your OS, Node and package manager versions. Security problems go through <a href="https://github.com/rez-rayan-zin-eddine/mfe-forge/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p>`,38)])])}const g=o(s,[["render",r]]);export{u as __pageData,g as default};
